package com.univmar.project; import com.univmar.common.api.ApiException; import com.univmar.customer.domain.*; import com.univmar.project.api.ProjectDtos.*; import com.univmar.project.domain.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class ProjectService {private final ProjectRepository projects;private final CustomerRepository customers;public ProjectService(ProjectRepository p,CustomerRepository c){projects=p;customers=c;}public ProjectResponse create(ProjectInput i){return response(projects.save(build(i)));}public ProjectResponse update(UUID id,ProjectInput i){Project p=entity(id);Project x=build(i);p.update(x.getCustomer(),x.getName(),x.getLocation(),x.getProjectType(),x.getDescription(),x.getEstimatedValue(),x.getStartDate(),x.getRequiredDeliveryDate(),x.getAssignedSalesAgent(),x.getStatus(),x.getNotes());return response(p);}@Transactional(readOnly=true)public ProjectResponse detail(UUID id){return response(entity(id));}@Transactional(readOnly=true)public ProjectPage list(String search,UUID customerId,ProjectStatus status,Pageable page){Specification<Project>s=Specification.where(null);if(search!=null&&!search.isBlank()){String q="%"+search.toLowerCase()+"%";s=s.and((r,x,b)->b.like(b.lower(r.get("name")),q));}if(customerId!=null)s=s.and((r,x,b)->b.equal(r.get("customer").get("id"),customerId));if(status!=null)s=s.and((r,x,b)->b.equal(r.get("status"),status));return ProjectPage.from(projects.findAll(s,page).map(this::response));}private Project build(ProjectInput i){Customer c=customers.findById(i.customerId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"CUSTOMER_NOT_FOUND","Customer was not found."));return new Project(c,i.name().trim(),t(i.location()),t(i.projectType()),t(i.description()),i.estimatedValue(),i.startDate(),i.requiredDeliveryDate(),t(i.assignedSalesAgent()),i.status(),t(i.notes()));}private Project entity(UUID id){return projects.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"PROJECT_NOT_FOUND","Project was not found."));}private ProjectResponse response(Project p){return new ProjectResponse(p.getId(),p.getCustomer().getId(),p.getCustomer().getName(),p.getName(),p.getLocation(),p.getProjectType(),p.getDescription(),p.getEstimatedValue(),p.getStartDate(),p.getRequiredDeliveryDate(),p.getAssignedSalesAgent(),p.getStatus(),p.getNotes());}private String t(String x){return x==null||x.isBlank()?null:x.trim();}}
